            //
            aOrbiterA = ((aOrbiterA + aOrbiterE) + 0x0D60C0958F46DF0CULL) + aOUSaltD[(((511U - aIndex) + 173U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x23F910A74B193D62ULL;
