            aOrbiterH = (((aWandererE + RotL64(aIngress, 5U)) + RotL64(aCarry, 23U)) + 0xB5CD8447BB9A2E0BULL) + aOASaltA[(((511U - aIndex) + 201U)) & S_SALT1];
