            aOrbiterK = ((aWandererG + RotL64(aScatter, 19U)) + RotL64(aCarry, 19U)) + 0x0F953C4B98E82276ULL;
            aOrbiterD = (aWandererC + RotL64(aPrevious, 43U)) + 0x9F9EF3135030FB0BULL;
            aOrbiterE = ((aWandererI + RotL64(aScatter, 35U)) + 0xB65A066E88BF8607ULL) + aOASaltD[((aIndex + 36U)) & S_SALT1];
