            //
            aOrbiterB = ((aOrbiterB + aOrbiterA) + 0x9612FD4FB5F6E8F4ULL) + aOUSaltA[(((511U - aIndex) + 59U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0x7DA0B97D0C36B823ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xB4A3C58AC2F4E6B7ULL), 23U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x31F59F8BD91E1EE6ULL;
