            aCross = TwistMix64::DiffuseA((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aCross, 23U) + RotL64(aIngress, 56U)) + (RotL64(aPrevious, 11U) ^ RotL64(aCarry, 39U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterF = ((aWandererB + RotL64(aIngress, 50U)) + RotL64(aCarry, 35U)) + 0xE4E7C5A91088E5CDULL;
            aOrbiterA = ((aWandererA + RotL64(aCross, 3U)) + RotL64(aCarry, 51U)) + 0xC12CBCA6A0FA9656ULL;
            aOrbiterC = ((aWandererD + RotL64(aPrevious, 39U)) + RotL64(aCarry, 43U)) + 0x550B7519DE59F9A5ULL;
            aOrbiterE = (aWandererF + RotL64(aScatter, 23U)) + 0xA903046ED51E033EULL;
            aOrbiterI = (aWandererK + RotL64(aCross, 35U)) + 0x2166DA3C6DDB8416ULL;
            aOrbiterJ = ((aWandererC + RotL64(aIngress, 43U)) + 0xDCC35DCFB4A812E0ULL) + aOASaltB[(((511U - aIndex) + 461U)) & S_SALT1];
            aOrbiterK = (aWandererE + RotL64(aPrevious, 58U)) + 0x084E4AA2D04FB789ULL;
            aOrbiterD = ((aWandererG + RotL64(aScatter, 11U)) + 0x5D4617E5E840989DULL) + aOASaltC[(((511U - aIndex) + 279U)) & S_SALT1];
            aOrbiterB = ((aWandererJ + RotL64(aPrevious, 29U)) + 0x8A0208F45BEF7B1BULL) + aOASaltF[(((511U - aIndex) + 129U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0xAB2489A75271943CULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterF) ^ 0xD9452AC0933E34CFULL) ^ aOUSaltB[((aIndex + 238U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x5D680D6D9E8085CFULL), 13U);
            //
