            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0x7B92CB25D2473A45ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0x43E50EE5145BF4C0ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xEDD08C442217B8A3ULL), 29U);
