            aOrbiterH = ((aWandererJ + RotL64(aPrevious, 37U)) + RotL64(aCarry, 5U)) + 0x5077E95665484D94ULL;
            aOrbiterA = ((aWandererH + RotL64(aScatter, 46U)) + 0x11B46525F82AC223ULL) + aOASaltE[(((511U - aIndex) + 329U)) & S_SALT1];
            aOrbiterK = ((aWandererF + RotL64(aCross, 21U)) + 0x7D851325B6F8E7BCULL) + aOASaltB[((aIndex + 444U)) & S_SALT1];
            aOrbiterD = (((aWandererI + RotL64(aScatter, 5U)) + RotL64(aCarry, 51U)) + 0x2F84E71FA0490BCDULL) + aOASaltH[((aIndex + 38U)) & S_SALT1];
            aOrbiterE = (((aWandererA + RotL64(aIngress, 53U)) + RotL64(aCarry, 35U)) + 0xAAE2AD80C8F6C11DULL) + aOASaltA[(((511U - aIndex) + 191U)) & S_SALT1];
