            //
            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0x33732DD07411F8FEULL) + aOUSaltE[((aIndex + 451U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0x1A0EB75F36FEDCFDULL;
