            aOrbiterH = ((aWandererA + RotL64(aPrevious, 13U)) + 0x8F5A8434E22AD526ULL) + aOASaltF[(((511U - aIndex) + 41U)) & S_SALT1];
            aOrbiterB = (((aWandererC + RotL64(aScatter, 35U)) + RotL64(aCarry, 35U)) + 0x3EEF4852A1A86F85ULL) + aOASaltH[(((511U - aIndex) + 348U)) & S_SALT1];
            aOrbiterI = (aWandererH + RotL64(aCross, 47U)) + 0xB33902121BD75863ULL;
            aOrbiterE = ((aWandererE + RotL64(aScatter, 5U)) + 0xD446D20BEB077A49ULL) + aOASaltB[((aIndex + 7U)) & S_SALT1];
            aOrbiterF = (((aWandererK + RotL64(aCross, 57U)) + RotL64(aCarry, 23U)) + 0xF230327F5C569A85ULL) + aOASaltA[((aIndex + 413U)) & S_SALT1];
