            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterC = (aWandererA + RotL64(aCross, 23U)) + 0xC37E2D12EFBF9783ULL;
            aOrbiterB = ((aWandererK + RotL64(aIngress, 43U)) + 0x63394834CD5D23A4ULL) + aOASaltE[((aIndex + 265U)) & S_SALT1];
            aOrbiterJ = (((aWandererJ + RotL64(aScatter, 5U)) + RotL64(aCarry, 39U)) + 0xC5EFC45A9897BCEAULL) + aOASaltC[(((511U - aIndex) + 507U)) & S_SALT1];
            aOrbiterH = ((aWandererF + RotL64(aPrevious, 14U)) + 0xED1333583AF929AFULL) + aOASaltF[(((511U - aIndex) + 101U)) & S_SALT1];
            aOrbiterD = ((aWandererD + RotL64(aIngress, 51U)) + RotL64(aCarry, 51U)) + 0x71475E9BAD3923A6ULL;
            aOrbiterG = (((aWandererC + RotL64(aCross, 57U)) + RotL64(aCarry, 13U)) + 0x2957E5B3C44D1302ULL) + aOASaltA[(((511U - aIndex) + 69U)) & S_SALT1];
            aOrbiterF = ((aWandererI + RotL64(aPrevious, 29U)) + 0xE8F88979D77023ECULL) + aOASaltH[(((511U - aIndex) + 202U)) & S_SALT1];
