            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x6B5B49B06D18B428ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x34EC7DB37F114BA0ULL;
