            //
            aOrbiterD = ((aOrbiterD + aOrbiterC) + 0xC20BDB6BAEAE82D4ULL) + aOUSaltG[((aIndex + 182U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterD) ^ 0x261C68689A17713CULL) ^ aOUSaltB[((aIndex + 444U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x3AD2AF6E70746375ULL), 3U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x0179BB18CD37BB2BULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0xD20BBF6359E5D1D5ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xA5C4397A69A34B1DULL), 11U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterJ) + 0x2C2B72E48AA1331DULL) + aOUSaltC[(((511U - aIndex) + 233U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x919EB18831114A92ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x495ABF07A89D3D07ULL), 35U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterF) + 0x6675B9E8499147B4ULL) + aOUSaltD[((aIndex + 224U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterH) ^ 0x9CEA308305A95395ULL) ^ aOUSaltH[((aIndex + 359U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xB871A78DEB7F1BEFULL), 21U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0xC5B84A81386ECA61ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x7468FE637A53EB84ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xD6657ED0B770D70BULL), 27U);
