            //
            aOrbiterJ = ((aWandererC + RotL64(aScatter, 5U)) + 0x41527B11EC9FCB3DULL) + aOASaltD[((aIndex + 284U)) & S_SALT1];
            aOrbiterD = (((aWandererI + RotL64(aCross, 21U)) + RotL64(aCarry, 39U)) + 0x05D6E5C0E7A73C19ULL) + aOASaltG[(((511U - aIndex) + 231U)) & S_SALT1];
