            aOrbiterA = ((aOrbiterA + aOrbiterI) + 0x55DD1DEA710E6214ULL) + aOUSaltH[(((511U - aIndex) + 170U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0xECE795B78871DD6FULL;
